    mockGeodataFetch((url) => {
      requested.push(url);
      return {
        ok: true,
        json: async () => ({
          type: 'FeatureCollection',
          features: [
            { type: 'Feature', geometry: { type: 'Point', coordinates: [18.05, 59.33] }, properties: {} },
